			// 3. Set up defer to unload program when this is closed
			defer func(id uint) {
				log.Printf("Closing Connection for Program: %d\n", id)
				_, err = c.Unload(ctx, &gobpfman.UnloadRequest{Id: uint32(id)})
				if err != nil {
					conn.Close()
					log.Print(err)
					return
				}
				conn.Close()
			}(paramData.ProgId)

