		log.Printf("Failed to load pinned Map: %s\n", mapPath)
		log.Print(err)
		return
	}

	// retrieve and report on the number of times the uprobe is executed.
	index := uint32(0)
	ticker := time.NewTicker(1 * time.Second)
	go func() {
