	v := &StateStorage{}
	for _, c := range pod.Spec.Containers {
		v.Add(c.Resources.Requests)
	}

	// 多个插件间数据传递使用
	state.Write("example", v)

	if pod.Spec.SchedulerName != ExampleName {
